 import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color, DoubleSide } = ctx.THREE;

  const root = new Group();
  root.name = config.id || 'journal-quote-panel';

  const width = 2.4;
  const height = 1.5;

  const geometry = new PlaneGeometry(width, height, 1, 1);

  const cardMaterial = new MeshBasicNodeMaterial({
    transparent: true,
    side: DoubleSide
  });

  const imageUrl = config.imageUrl ?? config.intent?.visualSpec?.imageUrl;
  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
      tex.colorSpace = ctx.THREE.SRGBColorSpace;
      cardMaterial.map = tex;
      cardMaterial.needsUpdate = true;
    });
  }

  const card = new Mesh(geometry, cardMaterial);
  card.name = 'quote-card';
  root.add(card);

  const edgeGeo = new PlaneGeometry(width + 0.05, height + 0.05, 1, 1);
  const edgeMaterial = new MeshBasicNodeMaterial({
    color: new Color('#ff2a38'),
    transparent: true,
    opacity: 0,
    depthWrite: false,
    side: DoubleSide
  });
  const edge = new Mesh(edgeGeo, edgeMaterial);
  edge.position.z = -0.005;
  edge.name = 'accent-edge';
  root.add(edge);

  const timelines = [];

  const primitiveRefs = [];
  const cpx = config.cinematicPrimitives ?? [];
  for (const primitive of cpx) {
    if (ctx.primitives[primitive.name]) {
      const ref = ctx.primitives[primitive.name](root, primitive.params ?? {});
      if (ref) primitiveRefs.push(ref);
    }
  }

  const clearTimelines = () => {
    for (const tl of timelines) {
      if (tl && typeof tl.kill === 'function') tl.kill();
    }
    timelines.length = 0;
  };

  const killTweensOnTargets = () => {
    gsap.killTweensOf(root.position);
    gsap.killTweensOf(root.scale);
    gsap.killTweensOf(edgeMaterial);
  };

  const setActive = (active) => {
    clearTimelines();
    killTweensOnTargets();

    const hoverTl = gsap.timeline();
    hoverTl.to(
      root.position,
      {
        y: active ? 0.15 : 0,
        duration: active ? 0.35 : 0.25,
        ease: active ? 'power2.out' : 'power2.inOut'
      },
      0
    );
    hoverTl.to(
      edgeMaterial,
      {
        opacity: active ? 0.55 : 0,
        duration: active ? 0.3 : 0.25,
        ease: 'power2.out'
      },
      0
    );
    timelines.push(hoverTl);
  };

  root.userData.handlers = {
    pointerover: (e) => {
      setActive(true);
    },
    pointerout: (e) => {
      setActive(false);
    },
    pointerdown: (e) => {
      const pressTl = gsap.timeline();
      pressTl.to(root.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'back.out(1.7)'
      });
      timelines.push(pressTl);
    },
    pointerup: (e) => {
      const releaseTl = gsap.timeline();
      releaseTl.to(root.scale, {
        x: 1,
        y: 1,
        z: 1,
        duration: 0.2,
        ease: 'power2.out'
      });
      timelines.push(releaseTl);
    },
    click: (e) => {
      ctx.emit('hub-journal.select', { id: config.id });
    }
  };

  root.userData.cleanup = () => {
    clearTimelines();
    killTweensOnTargets();

    for (const ref of primitiveRefs) {
      if (ref && typeof ref.cleanup === 'function') ref.cleanup();
    }

    geometry.dispose();
    cardMaterial.dispose();
    edgeGeo.dispose();
    edgeMaterial.dispose();

    if (cardMaterial.map && cardMaterial.map.dispose) {
      cardMaterial.map.dispose();
    }

    root.clear();
  };

  return root;
}
